style.css:
@-moz-document domain("jeuxvideo.com") {
.icon-topic-folder::before {
    content: "\EA7A";
  }

  .tablesForum__cellSubject {
    color: var(--jv-text-color);
  }

  .titleMessagesUsers__title {
    font-size: 1.3rem;
    line-height: 1;
  }

  .titleMessagesUsers__header {
    margin-bottom: 1.1rem;
  }

  .container__navTop {
    margin-bottom: 1.1rem;
  }

  .buttonsNavbar__sticky {
    margin-bottom: 1.5rem;
  }

  .container__pagination {
    margin-bottom: 1.5rem;
  }

  .tablesForum__bodyRow {
    padding: 0.4rem;
    padding-left: var(--tables-forums-row-padding-left);
    font-size: 0.9rem;
  }

  .buttonsNavbar .forumSearchBar__formInput {
    border: none;
    padding: 0.5rem;
  }

  .layout__breadcrumb {
    min-height: 2.6rem;
  }

  .spreadContainer {
    margin-bottom: 0;
  }

  .buttonsNavbar__sticky {
    position: static;
  }

  .messageUser__main {
    font-size: 1rem;
  }

  .message__urlImgSticker {
    max-width: 5rem;
    max-height: 5rem;
    min-width: 5rem;
    min-height: 0;
  }

  @media (min-width: 612px) {
    .buttonsNavbar {
      padding: 0.5rem 0.9375rem;
    }
  }

  @media (min-width: 1450px) {
    .layout {
      --grid-template-columns: 1fr 56rem 24.5rem 1fr;
    }
  }
}
